// Package bench is the forgemark benchmark engine: it drives real git
// push/clone operations against one target forge and reports per-level
// results. The CLI (cmd/forgemark) and the web server (internal/server) are
// both thin frontends over Runner.
package bench

import (
	"errors"
	"fmt"
	"net/url"
	"strconv"
	"strings"
	"time"

	"github.com/go-git/go-git/v6/plumbing"
)

// Target is one forge to benchmark: where to connect and how to authenticate.
// Supplying TokenURL or Jurisdiction selects the entiredb path (jurisdiction
// token exchange + node discovery); they mean nothing to any other forge, so
// their presence is the signal — no separate target-kind field.
type Target struct {
	Name      string   // display label; empty defaults to the remote base URL
	Remote    string   // base URL of the forge, e.g. https://gitlab.com
	Repos     []string // repo paths appended to Remote verbatim
	User      string   // basic-auth username (default x-access-token; token forges ignore it)
	Secret    string   // credential secret (forge token, or the entiredb subject token). Never serialized.
	Insecure  bool     // skip TLS verification
	ObjectFmt string   // "auto" | "sha1" | "sha256"

	// entiredb
	TokenURL     string // core /oauth/token endpoint (selects entiredb)
	Jurisdiction string // jurisdiction audience host, bare origin (selects entiredb)
	ClientID     string // public OAuth client id; empty defaults to entire-cli
}

// Workload is the target-independent shape of a run: strategy, sweep, and
// commit content. One Workload is shared by every target of a comparison run.
type Workload struct {
	RunID        string
	Strategy     string // branch | repo | clone | session
	BranchPrefix string
	Concurrency  []int
	Duration     time.Duration
	Warmup       time.Duration
	Commit       CommitConfig

	// session/clone strategies
	SessionCommits int
	CloneDepth     int
	BaseRef        string
}

// Validate applies the target-independent checks that parseFlags used to do,
// so the server rejects a bad workload with the same errors the CLI reports.
func (w Workload) Validate() error {
	switch w.Strategy {
	case "branch", "repo", "clone", "session":
	default:
		return fmt.Errorf("invalid -strategy %q (branch|repo|clone|session)", w.Strategy)
	}
	if w.Strategy == "session" && w.SessionCommits < 1 {
		return errors.New("-session-commits must be >= 1")
	}
	if len(w.Concurrency) == 0 {
		return errors.New("no concurrency levels")
	}
	for _, n := range w.Concurrency {
		if n < 1 {
			return fmt.Errorf("invalid concurrency %d", n)
		}
	}
	if w.Duration <= 0 {
		return errors.New("-duration must be > 0")
	}
	if w.Warmup < 0 {
		return errors.New("-warmup must be >= 0")
	}
	if w.Strategy != "clone" {
		if w.Commit.FilesMin < 1 {
			return errors.New("-files-min must be >= 1 (a commit needs a change to push)")
		}
		if w.Commit.FilesMax < w.Commit.FilesMin {
			return errors.New("-files-max < -files-min")
		}
		if w.Commit.FileSize < 1 {
			return errors.New("-file-size must be >= 1 (empty blobs reproduce → ErrEmptyCommit)")
		}
	}
	// Validate the assembled ref, not the prefix alone: validity is context-dependent
	// (a trailing "/" or bare word is fine mid-ref, invalid standalone). c/a are arbitrary —
	// only the prefix can invalidate it — so this one parse-time check covers the whole sweep.
	runID := w.RunID
	if runID == "" {
		runID = "fmX"
	}
	if err := plumbing.ReferenceName(DestRef(w.BranchPrefix, runID, 1, 0)).Validate(); err != nil {
		return fmt.Errorf("invalid -branch-prefix %q: %w", w.BranchPrefix, err)
	}
	return nil
}

// CommitDesc describes the commit content shape, e.g. "1-10 x 2048B".
func (w Workload) CommitDesc() string {
	return fmt.Sprintf("%d-%d x %dB", w.Commit.FilesMin, w.Commit.FilesMax, w.Commit.FileSize)
}

// NewRunID returns a fresh run identifier. Nanosecond resolution so two runs
// started back-to-back (a server restarting a sweep) can't collide.
func NewRunID() string {
	return "fm" + strconv.FormatInt(time.Now().UnixNano(), 36)
}

// DestRef builds an agent's destination branch ref, prepending branchPrefix
// verbatim before the run ID. Empty prefix reproduces the default name.
func DestRef(branchPrefix, runID string, c, i int) string {
	return fmt.Sprintf("refs/heads/%s%s-c%d-a%d", branchPrefix, runID, c, i)
}

// IsGitHubDotCom reports whether remote points at github.com (so the abuse
// warning + sha1 constraint apply). Any other host — GHES, GitLab, Gitea — is
// just a generic forge.
func IsGitHubDotCom(remote string) bool {
	u, err := url.Parse(remote)
	if err != nil {
		return false
	}
	return strings.EqualFold(u.Hostname(), "github.com")
}

package bench

import (
	"context"
	"encoding/json"
	"fmt"
	"io"
	"net/http"
	"net/url"
	"os"
	"strings"
	"sync"
	"time"

	githttp "github.com/go-git/go-git/v6/plumbing/transport/http"
	"golang.org/x/sync/singleflight"
)

// credentialProvider supplies the git HTTP basic-auth credential for a push.
// Two implementations cover every forge:
//
//	staticCreds       — a constant username/password (a GitHub/GitLab PAT, a
//	                    Gitea token, or plain basic auth). The common case.
//	jurisdictionCreds — the entiredb identity-token exchange: one short-lived
//	                    jurisdiction token for the whole region, refreshed
//	                    before it expires. Repo-independent, so the repo
//	                    argument is ignored.
type credentialProvider interface {
	basicAuth(ctx context.Context, repo string) (*githttp.BasicAuth, error)
}

// staticCreds returns the same credential for every push. Username is a
// forge-specific placeholder for token auth (github ignores it and treats the
// password as the token; gitlab accepts any username with a PAT).
type staticCreds struct {
	username string
	password string
}

func (s staticCreds) basicAuth(context.Context, string) (*githttp.BasicAuth, error) {
	return &githttp.BasicAuth{Username: s.username, Password: s.password}, nil
}

// jurisdictionCreds exchanges a subject token (a session/SA JWT carrying
// entire:session) for an entiredb jurisdiction token and caches the single
// result, refreshing before expiry. Unlike a per-repo push token, one
// jurisdiction token authorizes every repo the caller can reach — the data
// plane resolves each push live — so there's no per-repo audience and no
// per-repo cache. The exchange is the RFC 8693 shape: audience is the bare
// jurisdiction origin (e.g. https://us.example.com), scope is openid.
type jurisdictionCreds struct {
	httpc    *http.Client
	tokenURL string // core auth /oauth/token, e.g. https://us.auth.example.com/oauth/token
	audience string // jurisdiction host bare origin, e.g. https://us.example.com
	clientID string // public OAuth client, e.g. entire-cli
	subject  string // exchangeable subject JWT (must carry entire:session)
	username string // basic-auth username; Entire ignores it

	mu         sync.Mutex
	tok        tokenEntry
	refreshing bool               // a background ahead-of-expiry refresh is in flight
	sf         singleflight.Group // collapses concurrent cold exchanges into one
}

type tokenEntry struct {
	token string
	exp   time.Time
}

// singleflightKey is arbitrary: there is exactly one token, so all callers
// coalesce onto the same key.
const singleflightKey = "jurisdiction"

func newJurisdictionCreds(httpc *http.Client, tokenURL, audience, clientID, subject, username string) *jurisdictionCreds {
	return &jurisdictionCreds{
		httpc:    httpc,
		tokenURL: tokenURL,
		audience: strings.TrimRight(audience, "/"),
		clientID: clientID,
		subject:  subject,
		username: username,
	}
}

func (j *jurisdictionCreds) basicAuth(ctx context.Context, _ string) (*githttp.BasicAuth, error) {
	token, err := j.get(ctx)
	if err != nil {
		return nil, err
	}
	// Entire ignores the username; the token is the password.
	return &githttp.BasicAuth{Username: j.username, Password: token}, nil
}

// get returns a valid jurisdiction token. A still-valid token within 2 minutes
// of expiry is returned immediately while a single background refresh runs
// (serve-stale-while-revalidate): a mid-sweep refresh must not block every
// agent at once, or it injects a synchronized spike into the p99/max tail this
// harness reports. Only a missing/expired token blocks — and singleflight
// collapses those concurrent first-time exchanges (all agents at startup) into
// one /oauth call instead of a herd.
func (j *jurisdictionCreds) get(ctx context.Context) (string, error) {
	if err := ctx.Err(); err != nil {
		return "", fmt.Errorf("jurisdiction token fetch canceled: %w", err)
	}
	j.mu.Lock()
	e := j.tok
	valid := e.token != "" && time.Now().Before(e.exp)
	// Only a valid-but-aging token triggers an ahead-refresh. Guarding on
	// `valid` matters: an expired token also satisfies time.Until < 2m, and
	// setting refreshing=true here without entering the goroutine that clears
	// it would leak the flag and permanently disable ahead-refresh.
	startAhead := valid && time.Until(e.exp) < 2*time.Minute && !j.refreshing
	if startAhead {
		j.refreshing = true
	}
	j.mu.Unlock()

	if valid {
		if startAhead {
			go func() {
				defer func() {
					j.mu.Lock()
					j.refreshing = false
					j.mu.Unlock()
				}()
				// Best-effort: the cached token is still valid, so a failed
				// ahead-refresh just retries on a later get; surface it but
				// don't disrupt the sweep.
				if _, err := j.refreshNow(); err != nil {
					fmt.Fprintf(os.Stderr, "forgemark: background jurisdiction-token refresh failed: %v\n", err)
				}
			}()
		}
		return e.token, nil
	}
	return j.refreshNow() // no valid token: block on the collapsed exchange
}

// refreshNow exchanges a fresh token and caches it, with singleflight
// collapsing concurrent calls into one network exchange. The exchange runs on
// a detached, time-bounded context so a single caller's cancellation can't
// fail a refresh other agents are waiting on.
func (j *jurisdictionCreds) refreshNow() (string, error) {
	v, err, _ := j.sf.Do(singleflightKey, func() (any, error) {
		ctx, cancel := context.WithTimeout(context.Background(), 30*time.Second)
		defer cancel()
		e, err := j.exchange(ctx)
		if err != nil {
			return "", err
		}
		j.mu.Lock()
		j.tok = e
		j.mu.Unlock()
		return e.token, nil
	})
	if err != nil {
		return "", fmt.Errorf("jurisdiction token exchange: %w", err)
	}
	token, ok := v.(string)
	if !ok {
		return "", fmt.Errorf("jurisdiction token exchange: unexpected result type %T", v)
	}
	return token, nil
}

func (j *jurisdictionCreds) exchange(ctx context.Context) (tokenEntry, error) {
	form := url.Values{
		"grant_type":           {"urn:ietf:params:oauth:grant-type:token-exchange"},
		"subject_token_type":   {"urn:ietf:params:oauth:token-type:access_token"},
		"requested_token_type": {"urn:ietf:params:oauth:token-type:access_token"},
		"subject_token":        {j.subject},
		"audience":             {j.audience},
		"scope":                {"openid"},
	}
	req, err := http.NewRequestWithContext(ctx, http.MethodPost, j.tokenURL, strings.NewReader(form.Encode()))
	if err != nil {
		return tokenEntry{}, fmt.Errorf("build token request: %w", err)
	}
	req.Header.Set("Content-Type", "application/x-www-form-urlencoded")
	req.SetBasicAuth(j.clientID, "") // public client: empty secret is intentional

	resp, err := j.httpc.Do(req)
	if err != nil {
		return tokenEntry{}, err
	}
	defer func() { _ = resp.Body.Close() }()
	body, err := io.ReadAll(io.LimitReader(resp.Body, 1<<20))
	if err != nil {
		return tokenEntry{}, fmt.Errorf("read token response: %w", err)
	}
	if resp.StatusCode != http.StatusOK {
		return tokenEntry{}, fmt.Errorf("HTTP %d: %s", resp.StatusCode, strings.TrimSpace(string(body)))
	}
	var jr struct {
		AccessToken string `json:"access_token"`
		ExpiresIn   int    `json:"expires_in"`
	}
	if err := json.Unmarshal(body, &jr); err != nil {
		return tokenEntry{}, fmt.Errorf("decode: %w", err)
	}
	if jr.AccessToken == "" {
		return tokenEntry{}, fmt.Errorf("empty access_token")
	}
	ttl := jr.ExpiresIn
	if ttl <= 0 {
		ttl = 899 // ~15m default matching the jurisdiction-token TTL
	}
	return tokenEntry{token: jr.AccessToken, exp: time.Now().Add(time.Duration(ttl) * time.Second)}, nil
}

// forgemark — a concurrent git-push load generator for any smart-HTTP git forge.
//
// It answers the headline question: how many small pushes/sec can one repo
// sustain under many concurrent writers, and what's the per-push latency
// distribution? It drives REAL pushes through go-git (packfile build + ref
// update), so unlike a plain HTTP load tool it exercises the full receive-pack
// path.
//
// The forge is inferred from the flags, not an explicit -target:
//
//	any smart-HTTP host (GitLab, Gitea, Bitbucket, self-hosted, GHES, github.com)
//	    — push to <-remote>/<repo> (repo path appended verbatim; include a .git
//	    suffix in -repos if the forge needs it) with a static credential from the
//	    environment. A github.com remote additionally gets the abuse-detection
//	    warning above concurrency 16.
//	entiredb — selected by supplying -token-url and -jurisdiction: one
//	    jurisdiction identity token (RFC 8693 exchange, authorized live per push),
//	    direct-to-node push, node discovery via X-Entire-Replicas.
//
// Strategies (-strategy): branch (default; per-agent branches on one repo),
// repo (spread across N repos), clone (clone-only read loop), session
// (clone+push loop per agent).
//
// The benchmark engine itself lives in internal/bench; this package is the
// flag-driven CLI over it, and `forgemark serve` is the web GUI over the same
// engine.
//
// Only ever run this against infrastructure you own or are explicitly
// authorized to load-test.
package main

import (
	"context"
	"encoding/json"
	"errors"
	"flag"
	"fmt"
	"io"
	"os"
	"os/signal"
	"slices"
	"strconv"
	"strings"
	"syscall"
	"time"

	"github.com/entireio/forgemark/internal/bench"
)

func main() {
	// `forgemark serve` starts the web GUI; anything else is the classic
	// flag-driven CLI (which takes no positional args, so this can't collide).
	if len(os.Args) > 1 && os.Args[1] == "serve" {
		if err := runServe(os.Args[2:]); err != nil {
			fmt.Fprintln(os.Stderr, "forgemark: "+err.Error())
			os.Exit(1)
		}
		return
	}
	if err := run(); err != nil {
		fmt.Fprintln(os.Stderr, "forgemark: "+err.Error())
		os.Exit(1)
	}
}

// cliConfig is the parsed flag set: the single benchmark target, the shared
// workload shape, and CLI-only concerns (where the secret comes from, where
// results go).
type cliConfig struct {
	target    bench.Target
	workload  bench.Workload
	tokenFile string // path to the credential secret ("-" = stdin); preferred over $ACCESS_TOKEN
	out       string
}

func run() error {
	cfg, err := parseFlags()
	if err != nil {
		return err
	}

	secret, err := readSecret(cfg.tokenFile)
	if err != nil {
		return err
	}
	cfg.target.Secret = secret

	// The abuse warning is a CLI concern: the server surfaces the same check in
	// its UI instead of on stderr.
	if cfg.target.TokenURL == "" && cfg.target.Jurisdiction == "" && bench.IsGitHubDotCom(cfg.target.Remote) {
		if hi := slices.Max(cfg.workload.Concurrency); hi > 16 {
			fmt.Fprintf(os.Stderr, "forgemark: warning: concurrency %d against github.com is likely to trip "+
				"secondary rate limits / abuse detection — keep it low (e.g. -concurrency 1,4)\n", hi)
		}
	}

	ctx, stop := signal.NotifyContext(context.Background(), syscall.SIGINT, syscall.SIGTERM)
	defer stop()

	r, err := bench.NewRunner(ctx, cfg.target, cfg.workload, nil)
	if err != nil {
		return err
	}

	fmt.Printf("forgemark: target=%s strategy=%s repos=%d nodes=%d object-format=%s commit=%s\n",
		r.Label(), cfg.workload.Strategy, len(cfg.target.Repos), r.Nodes(), r.ObjectFormat(), cfg.workload.CommitDesc())
	fmt.Printf("           sweep=%v duration=%s warmup=%s\n", cfg.workload.Concurrency, cfg.workload.Duration, cfg.workload.Warmup)
	fmt.Println()

	var results []bench.LevelResult
	for _, c := range cfg.workload.Concurrency {
		if ctx.Err() != nil {
			break
		}
		res, err := r.RunLevel(ctx, c)
		if err != nil {
			return fmt.Errorf("concurrency=%d: %w", c, err)
		}
		results = append(results, res)
		printRow(res)
	}

	return writeResults(cfg, r.Label(), results)
}

// readSecret returns the credential secret from the most secure source
// available: -token-file (a file path, or "-" for stdin) if set, otherwise the
// ACCESS_TOKEN env var. A raw token on argv is intentionally unsupported — it
// would leak via ps(1) and shell history. The secret is the forge access token
// for a plain forge, or the subject token to exchange for Entire.
func readSecret(tokenFile string) (string, error) {
	if tokenFile != "" {
		var (
			b   []byte
			err error
		)
		if tokenFile == "-" {
			b, err = io.ReadAll(os.Stdin)
		} else {
			b, err = os.ReadFile(tokenFile)
		}
		if err != nil {
			return "", fmt.Errorf("read -token-file: %w", err)
		}
		if s := strings.TrimSpace(string(b)); s != "" {
			return s, nil
		}
		return "", errors.New("-token-file is empty")
	}
	if t := os.Getenv("ACCESS_TOKEN"); t != "" {
		return t, nil
	}
	return "", errors.New("no credential: pass -token-file <path|-> (recommended) or set ACCESS_TOKEN")
}

func parseFlags() (*cliConfig, error) {
	cfg := &cliConfig{}
	var reposCSV, pattern, concCSV string
	var repoCount int
	var durationFlag, warmupFlag time.Duration

	flag.StringVar(&cfg.target.Remote, "remote", "", "base URL of the forge, e.g. https://gitlab.com (repos are appended verbatim as <base>/<repo>); for Entire, the cluster base URL")
	flag.StringVar(&cfg.tokenFile, "token-file", "", "path to a file holding the credential secret (Entire: the subject token); \"-\" reads stdin. Preferred over $ACCESS_TOKEN — keeps the secret off argv")
	flag.StringVar(&cfg.target.User, "user", "", "basic-auth username for the credential (default x-access-token; token forges ignore it)")
	flag.StringVar(&reposCSV, "repos", "", "comma-separated repo paths, appended to -remote verbatim (e.g. you/bench.git)")
	flag.StringVar(&pattern, "repo-pattern", "", "repo path template; {n} is replaced by the index (1..N), used with -repo-count (e.g. you/bench-{n})")
	flag.IntVar(&repoCount, "repo-count", 0, "number of repos for -repo-pattern (expands {n} = 1..N)")
	flag.StringVar(&cfg.workload.Strategy, "strategy", "branch", "branch (one repo, per-agent branches) | repo (spread across repos) | clone (clone-only read loop) | session (clone+push loop per agent)")
	flag.StringVar(&cfg.workload.BranchPrefix, "branch-prefix", "", "prefix prepended verbatim to branch names, before the run ID (e.g. bench/ → refs/heads/bench/fm...-c1-a0); empty keeps the default")
	flag.StringVar(&concCSV, "concurrency", "1,8,32,128", "comma-separated writer counts to sweep")
	flag.DurationVar(&durationFlag, "duration", 60*time.Second, "measured window per concurrency level")
	flag.DurationVar(&warmupFlag, "warmup", 10*time.Second, "warm-up before measuring (excluded from stats)")
	flag.IntVar(&cfg.workload.Commit.FilesMin, "files-min", 1, "min changed files per commit")
	flag.IntVar(&cfg.workload.Commit.FilesMax, "files-max", 10, "max changed files per commit")
	flag.IntVar(&cfg.workload.Commit.FileSize, "file-size", 2048, "bytes per changed file")
	flag.StringVar(&cfg.target.ObjectFmt, "object-format", "auto", "auto | sha1 | sha256 (auto probes the entiredb advertisement; generic/github default sha1)")
	flag.BoolVar(&cfg.target.Insecure, "insecure", false, "skip TLS verification (dev/self-signed hosts)")
	flag.StringVar(&cfg.out, "out", "", "write JSON results here (default: results/forgemark-<id>.json)")
	flag.IntVar(&cfg.workload.SessionCommits, "session-commits", 5, "session strategy: commit+push checkpoints per cloned session")
	flag.IntVar(&cfg.workload.CloneDepth, "clone-depth", 1, "clone/session strategy: shallow clone depth (1=tip; 0=full history)")
	flag.StringVar(&cfg.workload.BaseRef, "base-ref", "", "clone/session strategy: branch to clone — bare name (main) or full ref (refs/heads/main); default: remote default branch")

	// entiredb: presence of -token-url/-jurisdiction selects the entiredb path.
	flag.StringVar(&cfg.target.TokenURL, "token-url", "", "entiredb: core /oauth/token endpoint, e.g. https://<region>.auth.example.com/oauth/token (selects entiredb)")
	flag.StringVar(&cfg.target.Jurisdiction, "jurisdiction", "", "entiredb: jurisdiction audience host (bare origin), e.g. https://<region>.example.com (selects entiredb)")
	flag.StringVar(&cfg.target.ClientID, "client-id", "entire-cli", "entiredb: public OAuth client id for the exchange")
	flag.Parse()

	cfg.workload.Duration = durationFlag
	cfg.workload.Warmup = warmupFlag

	repos, err := expandRepos(reposCSV, pattern, repoCount)
	if err != nil {
		return nil, err
	}
	cfg.target.Repos = repos
	if cfg.workload.Strategy == "repo" && len(repos) < 2 {
		return nil, errors.New("strategy=repo needs >= 2 repos")
	}
	for _, p := range bench.SplitCSV(concCSV) {
		n, err := strconv.Atoi(p)
		if err != nil || n < 1 {
			return nil, fmt.Errorf("invalid concurrency %q", p)
		}
		cfg.workload.Concurrency = append(cfg.workload.Concurrency, n)
	}
	cfg.workload.RunID = bench.NewRunID()
	if err := cfg.workload.Validate(); err != nil {
		return nil, err
	}
	return cfg, nil
}

// expandRepos builds the target repo list from the mutually-exclusive
// -repos / -repo-pattern flags. Paths are used verbatim downstream (the
// endpoint appends them to the node with no rewriting), so this only validates
// and expands {n}; it never rewrites the path shape.
func expandRepos(reposCSV, pattern string, count int) ([]string, error) {
	repos := bench.SplitCSV(reposCSV)
	switch {
	case len(repos) > 0 && pattern != "":
		return nil, errors.New("pass -repos or -repo-pattern, not both")
	case len(repos) > 0:
		if count > 0 {
			return nil, errors.New("-repo-count applies to -repo-pattern, not -repos")
		}
		return repos, nil
	case pattern != "":
		if count <= 0 {
			return nil, errors.New("-repo-pattern requires -repo-count > 0")
		}
		if !strings.Contains(pattern, "{n}") {
			return nil, errors.New("-repo-pattern must contain the {n} index placeholder (e.g. you/bench-{n})")
		}
		for i := 1; i <= count; i++ {
			repos = append(repos, strings.ReplaceAll(pattern, "{n}", strconv.Itoa(i)))
		}
		return repos, nil
	case count > 0:
		return nil, errors.New("-repo-count requires -repo-pattern")
	default:
		return nil, errors.New("no repos: pass -repos or -repo-pattern + -repo-count")
	}
}

func printRow(r bench.LevelResult) {
	if r.Strategy == "clone" {
		fmt.Printf("  c=%-4d clone_ok=%-6d clone/s=%-8.1f p50=%-7.1f p95=%-8.1f p99=%-8.1f max=%-8.1f clone_err=%d\n",
			r.Concurrency, r.OK, r.OpsPerSec, r.P50ms, r.P95ms, r.P99ms, r.Maxms, r.OtherErrors)
		return
	}
	fmt.Printf("  c=%-4d push_ok=%-6d push/s=%-8.1f p50=%-7.1f p95=%-8.1f p99=%-8.1f max=%-8.1f cas=%d err=%d\n",
		r.Concurrency, r.OK, r.OpsPerSec, r.P50ms, r.P95ms, r.P99ms, r.Maxms, r.CASFailures, r.OtherErrors)
	if r.Clones > 0 {
		fmt.Printf("        clones=%-5d clone_ok=%-5d clone_p50=%-7.1f clone_p95=%-8.1f clone_p99=%-8.1f clone_err=%d\n",
			r.Clones, r.CloneOK, r.CloneP50ms, r.CloneP95ms, r.CloneP99ms, r.CloneErrors)
	}
}

func writeResults(cfg *cliConfig, label string, results []bench.LevelResult) error {
	out := cfg.out
	if out == "" {
		if err := os.MkdirAll("results", 0o750); err != nil {
			return fmt.Errorf("mkdir results: %w", err)
		}
		out = fmt.Sprintf("results/forgemark-%s.json", cfg.workload.RunID)
	}
	doc := map[string]any{
		"run_id":     cfg.workload.RunID,
		"target":     label,
		"strategy":   cfg.workload.Strategy,
		"duration":   cfg.workload.Duration.String(),
		"warmup":     cfg.workload.Warmup.String(),
		"repo_count": len(cfg.target.Repos),
		"commit":     cfg.workload.CommitDesc(),
		"levels":     results,
	}
	b, err := json.MarshalIndent(doc, "", "  ")
	if err != nil {
		return fmt.Errorf("marshal results: %w", err)
	}
	if err := os.WriteFile(out, b, 0o600); err != nil {
		return fmt.Errorf("write results: %w", err)
	}
	fmt.Printf("\nwrote %s\n", out)
	return nil
}

