/* ForgeMark dashboard — dark theme.
   Chrome/ink/palette values follow the validated reference palette
   (dark surface #1a1a19; categorical slots stepped for it). */

:root {
  --page:        #0d0d0d;
  --surface:     #1a1a19;
  --surface-2:   #222221;
  --ink:         #ffffff;
  --ink-2:       #c3c2b7;
  --muted:       #898781;
  --grid:        #2c2c2a;
  --baseline:    #383835;
  --border:      rgba(255, 255, 255, 0.10);
  --good:        #0ca30c;
  --warning:     #fab219;
  --critical:    #d03b3b;
  --accent:      #3987e5;

  --s1: #3987e5; /* blue    */
  --s2: #199e70; /* aqua    */
  --s3: #c98500; /* yellow  */
  --s4: #008300; /* green   */
  --s5: #9085e9; /* violet  */
  --s6: #e66767; /* red     */
  --s7: #d55181; /* magenta */
  --s8: #d95926; /* orange  */
}

* { box-sizing: border-box; }

body {
  margin: 0;
  background: var(--page);
  color: var(--ink-2);
  font: 14px/1.5 system-ui, -apple-system, "Segoe UI", sans-serif;
}

/* ---------- chrome ---------- */

.topbar {
  display: flex;
  align-items: center;
  gap: 28px;
  padding: 0 24px;
  height: 52px;
  background: var(--surface);
  border-bottom: 1px solid var(--border);
  position: sticky;
  top: 0;
  z-index: 10;
}
.brand {
  font-weight: 700;
  font-size: 16px;
  color: var(--ink);
  text-decoration: none;
  letter-spacing: 0.2px;
}
.brand span { color: var(--accent); }

content.content:
.seg { display: inline-flex; border: 1px solid var(--baseline); border-radius: 6px; overflow: hidden; margin-left: auto; }
.seg button { border: 0; border-radius: 0; padding: 3px 10px; font-size: 12px; font-weight: 500; background: transparent; color: var(--muted); }
.seg button.on { background: var(--surface-2); color: var(--ink); }

/* uPlot restyle for the dark surface */
.u-legend { font: 12px system-ui, sans-serif; color: var(--ink-2); text-align: left; margin-top: 2px; }
.u-legend .u-marker { border-radius: 2px; }
.u-legend th { font-weight: 500; }
.u-legend .u-value { color: var(--muted); font-variant-numeric: tabular-nums; }
.u-select { background: rgba(57, 135, 229, 0.15); }

/* ---------- tables ---------- */

table.results { width: 100%; border-collapse: collapse; font-variant-numeric: tabular-nums; }
table.results th, table.results td { padding: 6px 10px; text-align: right; border-bottom: 1px solid var(--grid); }
table.results th { color: var(--muted); font-size: 11px; font-weight: 500; text-transform: uppercase; letter-spacing: 0.4px; }
table.results td:first-child, table.results th:first-child { text-align: left; }
table.results td { color: var(--ink-2); }
table.results td.tname { color: var(--ink); font-weight: 550; }
table.results tr.lvl-first td { border-top: 1px solid var(--baseline); }
table.results .num-bad { color: var(--critical); }

.hist-row { display: flex; gap: 12px; align-items: center; padding: 10px 4px; border-bottom: 1px solid var(--grid); }
