1	// Package server is the forgemark web GUI: a localhost HTTP server that runs
2	// benchmark sweeps (one or many targets, level-aligned) over internal/bench
3	// and streams live per-second stats to an embedded single-page UI over SSE.
4	package server
5	
6	import (
7		"context"
8		"embed"
9		"encoding/json"
10		"errors"
11		"fmt"
12		"io/fs"
13		"net"
14		"net/http"
15		"net/url"
16		"time"
17	
18		"github.com/entireio/forgemark/internal/results"
19	)
20	
21	//go:embed static
22	var staticFiles embed.FS
23	
24	type Server struct {
25		addr string
26		mgr  *RunManager
27		mux  *http.ServeMux
28	}
29	
30	// New builds the server. resultsDir is where finished runs are persisted and
31	// where history is read from (shared with the CLI's results/ by default).
32	func New(addr, resultsDir string) *Server {
33		s := &Server{addr: addr, mgr: newRunManager(resultsDir), mux: http.NewServeMux()}
34	
35		staticRoot, err := fs.Sub(staticFiles, "static")
36		if err != nil {
37			panic("embedded static assets missing: " + err.Error()) // build-time invariant
38		}
39		s.mux.Handle("GET /", http.FileServerFS(staticRoot))
40	
41		s.mux.HandleFunc("POST /api/runs", s.requireLocalOrigin(s.handleStartRun))
42		s.mux.HandleFunc("GET /api/runs", s.handleListRuns)
43		s.mux.HandleFunc("GET /api/runs/{id}", s.handleGetRun)
44		s.mux.HandleFunc("POST /api/runs/{id}/cancel", s.requireLocalOrigin(s.handleCancelRun))
45		s.mux.HandleFunc("GET /api/runs/{id}/events", s.handleRunEvents)
46		s.mux.HandleFunc("GET /api/history", s.handleHistory)
47		s.mux.HandleFunc("GET /api/history/{file}", s.handleHistoryDoc)
48		return s
49	}
50	
51	// Handler exposes the mux for httptest.
52	func (s *Server) Handler() http.Handler { return s.mux }
53	
54	// ListenAndServe blocks until ctx is cancelled or the listener fails.
55	func (s *Server) ListenAndServe(ctx context.Context) error {
56		srv := &http.Server{Addr: s.addr, Handler: s.mux, ReadHeaderTimeout: 10 * time.Second}
57		errc := make(chan error, 1)
58		go func() { errc <- srv.ListenAndServe() }()
59		select {
60		case err := <-errc:
61			return err
62		case <-ctx.Done():
63			shutCtx, cancel := context.WithTimeout(context.Background(), 3*time.Second)
64			defer cancel()
65			_ = srv.Shutdown(shutCtx)
66			return nil
67		}
68	}
69	
70	// requireLocalOrigin guards mutating endpoints against DNS-rebinding/CSRF: the
71	// UI pastes credentials, so a hostile web page must not be able to drive this
72	// API. Browsers always send Origin on cross-origin POSTs; a request with no
73	// Origin header is curl or same-origin-old-browser, which is fine for a
74	// loopback tool.
75	func (s *Server) requireLocalOrigin(next http.HandlerFunc) http.HandlerFunc {
76		return func(w http.ResponseWriter, r *http.Request) {
77			if origin := r.Header.Get("Origin"); origin != "" {
78				u, err := url.Parse(origin)
79				if err != nil || !isLoopbackHost(u.Hostname()) {
80					http.Error(w, "forbidden origin", http.StatusForbidden)
81					return
82				}
83			}
84			next(w, r)
85		}
86	}
