function tickClock() {
  if (state.done) return;
  if (!state.curLevel) { clock.textContent = '–:––'; return; }
  const l = state.curLevel;
  const t0 = Date.parse(l.at) / 1000;
  const total = l.warmup_sec + l.duration_sec;
  const elapsed = Math.min(Date.now() / 1000 - t0, total);
  const remain = Math.max(0, Math.ceil(total - elapsed));
  clock.textContent = `${Math.floor(remain / 60)}:${String(remain % 60).padStart(2, '0')}`;
  phase.textContent = elapsed < l.warmup_sec ? 'warming up' : `c=${l.concurrency} · racing`;
}

