.brand span { color: var(--accent); }
.topbar nav { display: flex; gap: 4px; }
.topbar nav a {
  color: var(--ink-2);
  text-decoration: none;
  padding: 6px 12px;
  border-radius: 6px;
  font-weight: 500;
}
.topbar nav a:hover { background: var(--surface-2); color: var(--ink); }
.topbar nav a.active { background: var(--surface-2); color: var(--ink); }

main { max-width: 1180px; margin: 0 auto; padding: 24px; }

h1 { font-size: 20px; color: var(--ink); margin: 0 0 4px; }
h2 { font-size: 15px; color: var(--ink); margin: 0 0 12px; }
.sub { color: var(--muted); margin: 0 0 20px; }

.card {
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: 10px;
  padding: 18px 20px;
  margin-bottom: 16px;
}

/* ---------- forms ---------- */

label { display: block; font-size: 12px; color: var(--muted); margin-bottom: 4px; }
input[type="text"], input[type="password"], input[type="number"], select {
  width: 100%;
  background: var(--page);
  border: 1px solid var(--baseline);
  border-radius: 6px;
  color: var(--ink);
  padding: 7px 10px;
  font: inherit;
}
input:focus, select:focus { outline: 1px solid var(--accent); border-color: var(--accent); }
.grid { display: grid; gap: 12px 14px; }
.grid.c4 { grid-template-columns: repeat(4, 1fr); }
.grid.c3 { grid-template-columns: repeat(3, 1fr); }
.grid.c2 { grid-template-columns: repeat(2, 1fr); }
.field.wide { grid-column: 1 / -1; }
@media (max-width: 800px) { .grid.c4, .grid.c3 { grid-template-columns: repeat(2, 1fr); } }

button {
  font: inherit;
  font-weight: 600;
  border: 1px solid var(--baseline);
  background: var(--surface-2);
  color: var(--ink);
  border-radius: 7px;
  padding: 8px 16px;
  cursor: pointer;
}
button:hover { border-color: var(--muted); }
button.primary { background: var(--accent); border-color: var(--accent); color: #fff; }
button.primary:hover { filter: brightness(1.1); }
button.primary:disabled { opacity: 0.45; cursor: not-allowed; filter: none; }
button.danger { border-color: var(--critical); color: var(--critical); background: transparent; }
button.small { padding: 4px 10px; font-size: 12px; font-weight: 500; }
button.link { background: none; border: none; color: var(--accent); padding: 2px 4px; font-weight: 500; }

.target-card {
  border: 1px solid var(--baseline);
  border-left: 3px solid var(--tcolor, var(--muted));
  border-radius: 8px;
  padding: 14px 16px;
  margin-bottom: 12px;
  background: var(--surface);
}
.target-card .thead {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 10px;
}
.target-card .thead .tname { font-weight: 600; color: var(--ink); }
details.entire { margin-top: 10px; }
details.entire summary { cursor: pointer; color: var(--muted); font-size: 12px; }
details.entire .grid { margin-top: 10px; }

.confirm-row {
  display: flex;
  gap: 10px;
  align-items: flex-start;
  padding: 12px 14px;
  border: 1px solid var(--warning);
  border-radius: 8px;
  background: rgba(250, 178, 25, 0.06);
  margin: 16px 0;
}
.confirm-row input { margin-top: 3px; }
.confirm-row label { font-size: 13px; color: var(--ink-2); margin: 0; }

.banner {
  padding: 10px 14px;
  border-radius: 8px;
  margin-bottom: 12px;
  font-size: 13px;
  border: 1px solid var(--border);
}
.banner.warn { border-color: var(--warning); background: rgba(250, 178, 25, 0.08); color: var(--ink); }
.banner.error { border-color: var(--critical); background: rgba(208, 59, 59, 0.10); color: var(--ink); }

/* ---------- dashboard ---------- */

