    h('p', { class: 'eyebrow' }, 'ForgeMark'),
    h('h1', {}, 'New benchmark run'),
    h('p', { class: 'sub' }, 'Drive real git push/clone load against one or more forges and watch them race, live. Pick how you want to start:'),
    body);

  app.append(form);
  renderBody();
}

