    errorBanner = null;
    if (mode === 'demo') {
      targets = DEMO_PAIR.map((d) => blankTarget(d));
      applyRacePreset();
    } else if (mode === 'forges') {
      targets = [];
      applyRacePreset();
      addFromCLI();
    } else if (mode === 'custom') {
