1	// CLI-sourced credentials and target discovery. The GUI is a loopback control
2	// panel on the operator's own machine, so instead of pasting a token into the
3	// form, a target can name a secret_source ("gh" | "entire") and the server
4	// pulls the credential from the operator's already-authenticated CLI at run
5	// start. The token then never appears in any request or response body, and
6	// the browser never holds it at all.
7	
8	package server
9	
10	import (
11		"bytes"
12		"context"
13		"encoding/json"
14		"fmt"
15		"net/http"
16		"os/exec"
17		"strings"
18		"sync"
19		"time"
20	)
21	
22	const cliTimeout = 15 * time.Second
23	
24	// secretSources maps a TargetSpec.SecretSource to the fixed argv that prints
25	// the credential. Nothing user-controlled is ever executed: an unknown source
26	// is an error, never a command.
27	var secretSources = map[string][]string{
28		"gh":     {"gh", "auth", "token"},
29		"entire": {"entire", "auth", "token"},
30	}
31	
32	func resolveSecretSource(source string) (string, error) {
33		argv, ok := secretSources[source]
34		if !ok {
35			return "", fmt.Errorf("unknown secret_source %q (gh | entire)", source)
36		}
37		out, err := runCLI(argv...)
38		if err != nil {
39			return "", err
40		}
41		if out == "" {
42			return "", fmt.Errorf("%s printed an empty token", strings.Join(argv, " "))
43		}
44		return out, nil
45	}
46	
47	func runCLI(argv ...string) (string, error) {
48		ctx, cancel := context.WithTimeout(context.Background(), cliTimeout)
49		defer cancel()
50		cmd := exec.CommandContext(ctx, argv[0], argv[1:]...)
51		var stdout, stderr bytes.Buffer
52		cmd.Stdout, cmd.Stderr = &stdout, &stderr
53		if err := cmd.Run(); err != nil {
54			msg := strings.TrimSpace(stderr.String())
55			if msg == "" {
56				msg = err.Error()
57			}
58			if i := strings.IndexByte(msg, '\n'); i >= 0 {
59				msg = msg[:i]
60			}
61			return "", fmt.Errorf("%s: %s (is it installed and logged in?)", strings.Join(argv, " "), msg)
62		}
63		return strings.TrimSpace(stdout.String()), nil
64	}
65	
66	// suggestEntry is one CLI-discovered target template: a ready-to-post
67	// TargetSpec with SecretSource set and Secret empty, or the reason discovery
68	// failed. Note flags anything the operator still has to ensure themselves.
69	type suggestEntry struct {
70		Target *TargetSpec `json:"target,omitempty"`
71		Note   string      `json:"note,omitempty"`
72		Error  string      `json:"error,omitempty"`
73	}
74	
75	// handleLocalSuggest builds target templates from the operator's gh and
76	// entire CLI logins. It runs the same discovery scripts/compare-local.sh
77	// does: GitHub login → conventional throwaway repo; entire auth context →
78	// jurisdiction endpoints + default cluster + conventional native repo.
79	func (s *Server) handleLocalSuggest(w http.ResponseWriter, _ *http.Request) {
80		var gh, entire suggestEntry
81		var wg sync.WaitGroup
82		wg.Add(2)
83		go func() { defer wg.Done(); gh = suggestGitHub() }()
84		go func() { defer wg.Done(); entire = suggestEntire() }()
85		wg.Wait()
86		writeJSON(w, http.StatusOK, map[string]suggestEntry{"github": gh, "entire": entire})
87	}
88	
89	func suggestGitHub() suggestEntry {
90		login, err := runCLI("gh", "api", "user", "--jq", ".login")
91		if err != nil {
92			return suggestEntry{Error: err.Error()}
93		}
94		repo := login + "/forgemark-target"
95		return suggestEntry{
96			Target: &TargetSpec{
97				Name:         "github",
98				Remote:       "https://github.com",
99				Repos:        []string{repo},
100				SecretSource: "gh",
101			},
102			Note: fmt.Sprintf("repo %s must exist — scripts/compare-local.sh provisions it", repo),
103		}
104	}
105	
106	func suggestEntire() suggestEntry {
107		// The two CLI calls are independent (the status output is only consulted
108		// after both return), so run them concurrently — each can take up to
109		// cliTimeout, and serial worst case would double the suggest latency.
110		var (
111			status, clustersJSON   string
112			statusErr, clustersErr error
113			wg                     sync.WaitGroup
114		)
115		wg.Add(2)
