	if err := os.WriteFile(filepath.Join(dir, "forgemark-fmold.json"), []byte(legacy), 0o600); err != nil {
		t.Fatal(err)
	}
	doc, err := Load(dir, "forgemark-fmold.json")
	if err != nil {
